def check_self_intersection(n, x_coords):
    # Convert coordinates into tuples and sort by x-coordinate
    points = sorted((x, 0) for x in x_coords)

    # Function to determine if two segments (p1, p2) and (p3, p4) intersect
    def do_intersect(p1, p2, p3, p4):
        def ccw(A, B, C):
            return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])
        return ccw(p1, p3, p4) != ccw(p2, p3, p4) and ccw(p1, p2, p3) != ccw(p1, p2, p4)

    # Check intersections between consecutive points and wrap-around
    for i in range(n):
        # Current segment is from points[i] to points[(i + 1) % n]
        # Semi-circle from the first point of the segment to the second point
        p1, p2 = points[i], points[(i + 1) % n]

        # Other segments to check intersection
        for j in range(i + 2, i + n - 1):
            p3, p4 = points[j % n], points[(j + 1) % n]
            if do_intersect(p1, p2, p3, p4):
                return "yes"

    return "no"

